-- ---------------------------------------------------------------------------
-- Content versions (version 1, latest) for the corpus, so relevant_evidence
-- and expected_citations carry a resolvable content_version.
-- ---------------------------------------------------------------------------
INSERT INTO content_versions (content_item_id, author_id, version_number, storage_type, storage_key, diff_summary, status, is_latest, created_at)
SELECT id, author_id, 1, 'full', description, 'initial version from rag eval seed', 'active', true, NOW()
FROM content_items
WHERE id BETWEEN 1001 AND 1039
ON CONFLICT (content_item_id, version_number) DO UPDATE SET
  is_latest = true,
  storage_key = EXCLUDED.storage_key;

